HEADERS = {'Arduino.h': '\n#pragma once\n#include <cstdint>\n#include <cstdio>\n#include <cstring>\n#include <string>\n#include <deque>\n#include <vector>\n#include <utility>\n#define HIGH 1\n#define LOW 0\n#define INPUT 1\n#define OUTPUT 2\n#define INPUT_PULLUP 3\ninline uint32_t clockMs=0;\ninline int pinLevels[64]={};\ninline std::vector<std::pair<int,int>> writes, modes;\ninline uint32_t millis(){return clockMs;}\ninline int digitalRead(int p){return pinLevels[p];}\ninline void digitalWrite(int p,int v){pinLevels[p]=v;writes.emplace_back(p,v);}\ninline void pinMode(int p,int v){modes.emplace_back(p,v);}\nstruct SerialStub {\n  std::deque<unsigned char> rx; std::string tx;\n  void begin(int){} int available(){return rx.size();}\n  int read(){if(rx.empty())return -1;int c=rx.front();rx.pop_front();return c;}\n  int availableForWrite(){return 512;}\n  size_t write(const uint8_t* p,size_t n){tx.append((const char*)p,n);return n;}\n};\ninline SerialStub Serial;\n\ninline uint32_t servoDuty=0;\ninline bool ledcAttach(int,int,int){return true;}\ninline double ledcSetup(int,int,int){return 50;}\ninline void ledcAttachPin(int,int){}\ninline bool ledcWrite(int,uint32_t duty){servoDuty=duty;return true;}\n', 'Wire.h': '#pragma once\ninline int observedSda=-1,observedScl=-1;\nstruct WireStub {bool begin(int a,int b,int){observedSda=a;observedScl=b;return true;}void setTimeOut(int){}};inline WireStub Wire;\n', 'Adafruit_SHT31.h': '#pragma once\n#include <cmath>\n#include <vector>\ninline int shtAllowed=0x45;inline bool shtReadOK=true;inline std::vector<int> shtAttempts;\nstruct Adafruit_SHT31 {bool begin(int address){shtAttempts.push_back(address);return address==shtAllowed;}bool readBoth(float* t,float* h){*t=23.0f;*h=48.0f;return shtReadOK;}};\n', 'esp_random.h': '#pragma once\n#include <cstdint>\ninline uint32_t esp_random(){static uint32_t x=12345;return ++x;}\n', 'driver/gpio.h': '#pragma once\nusing gpio_num_t=int; inline int gpio_set_level(int p,int v){digitalWrite(p,v);return 0;}\n'}
